import {secretScanningPermissionAuditPath} from '../../../../paths'
import type {Alert, PermissionsCollection} from '../../../../types/alert-types'
import {useQuery} from '@github-ui/react-query'
import {verifiedFetch} from '@github-ui/verified-fetch'
import type {Repository} from '../../../../types/repo-types'
import {SkeletonText} from '@primer/react/experimental'
import {PermissionsTable} from '../PermissionsTable'
import {Link} from '@primer/react'
import {AIRemediationFeedback} from './components/AIRemediationFeedback'

export interface PermissionAuditDetails {
  summary: string
  permissions?: PermissionsCollection
  fallback: boolean
}

export function GenerationStep({
  alert,
  repository,
  hasMetadata,
}: {
  alert: Alert
  repository: Repository
  hasMetadata: boolean
}) {
  const aiPermissionAuditUrl = secretScanningPermissionAuditPath(
    repository.owner_display_login,
    repository.name,
    alert.number,
  )

  const permissionAuditFallback: PermissionAuditDetails = {
    summary: 'View audit log events for this token to see what permissions might be able to be removed.',
    permissions: undefined,
    fallback: true,
  }

  const {isLoading: isPermissionAuditLoading, data: permissionAuditDetails = permissionAuditFallback} = useQuery({
    queryKey: ['secret-scanning', aiPermissionAuditUrl],
    staleTime: Infinity,
    queryFn: async (): Promise<PermissionAuditDetails> => {
      try {
        const result = await verifiedFetch(aiPermissionAuditUrl, {
          method: 'get',
        })
        if (!result.ok) {
          return permissionAuditFallback
        }
        const res = await result.json()
        return res
      } catch {
        return permissionAuditFallback
      }
    },
    enabled: !!alert.feature_flags?.secret_scanning_display_alert_permissions && hasMetadata,
  })

  return (
    <Generation
      isPermissionAuditLoading={isPermissionAuditLoading}
      permissionAudit={permissionAuditDetails}
      generationLink={
        alert.token_type === 'GITHUB_TOKEN_V2'
          ? 'https://github.com/settings/personal-access-tokens'
          : 'https://github.com/settings/tokens'
      }
      hasMetadata={hasMetadata}
    />
  )
}

function Generation({
  permissionAudit,
  isPermissionAuditLoading,
  generationLink,
  hasMetadata,
}: {
  permissionAudit: PermissionAuditDetails
  isPermissionAuditLoading: boolean
  generationLink: string
  hasMetadata: boolean
}) {
  return (
    <div className="tmp-pl-3 tmp-pr-3 tmp-pb-3 pt-2" data-testid="secret-scanning-generation-step">
      {hasMetadata && (
        <>
          <p className="f5 text-semibold mb-2">Can we reduce the scopes of this secret?</p>
          {isPermissionAuditLoading ? <SkeletonText lines={3} /> : <p>{permissionAudit.summary}</p>}
          <PermissionsTable collection={permissionAudit.permissions} title={'Recommended permission changes'} />
        </>
      )}

      {!permissionAudit.fallback && hasMetadata && (
        <>
          <br />
          <AIRemediationFeedback stepName="generation" />
        </>
      )}

      <p className="f5 text-semibold mb-2">How do I generate a new secret?</p>
      <p>
        You can generate a new GitHub Personal Access Token in your developer settings:{' '}
        <Link inline href={generationLink}>
          {generationLink}
        </Link>
        . You can select “Generate a new token” and select your desired permissions.
      </p>
    </div>
  )
}
