export interface Repository {
  name: string
  owner_display_login: string
  owner_type: OwnerType
  owner_belongs_to_business: boolean
  visibility: RepositoryVisibility
}

export interface RepositoryWithOwner {
  name: string
  owner_display_login: string
}

export const OwnerType = {
  UserOwner: 'USER',
  OrgOwner: 'ORGANIZATION',
  UnknownOwner: 'UNKNOWN',
} as const

export type OwnerType = (typeof OwnerType)[keyof typeof OwnerType]

export const RepositoryVisibility = {
  public: 'public',
  internal: 'internal',
  private: 'private',
} as const

export type RepositoryVisibility = (typeof RepositoryVisibility)[keyof typeof RepositoryVisibility]
