import {CounterLabel, Flash, Heading, Link, Truncate, Dialog, Button} from '@primer/react'
import {StopIcon, CopilotIcon} from '@primer/octicons-react'
import {useState} from 'react'
import {AlertStatus, showAIAssistedRemediationGuidance} from '../../../types/alert-types'
import type {TokenVerificationStatus, Alert, Validation, OnDemandValidation} from '../../../types/alert-types'
import {verificationStatusActive, verificationStatusInactive} from '../../shared/VerificationStatus'
import {CopyToClipboardButton} from '@github-ui/copy-to-clipboard/Button'
import type {Repository} from '../../../types/repo-types'
import {Multipart} from './Multipart'
import {VerificationStatusHeading} from './Heading'
import {isOneClickReportable, Report} from './Report'

import styles from './Remediation.module.css'
import {clsx} from 'clsx'

export function Remediation({
  alert,
  hostName,
  repo,
  automaticPartnerValidityChecksEnabled,
  oneClickReportingAvailable,
}: {
  alert: Alert
  hostName: string
  repo: Repository
  automaticPartnerValidityChecksEnabled: boolean
  oneClickReportingAvailable: boolean
}) {
  const alertStatus: AlertStatus = alert.is_closed ? AlertStatus.CLOSED : AlertStatus.OPEN
  const alertValidationDetails: Validation = {
    validity: alert.validity,
    token_groups: alert.token_groups,
    validity_last_checked: alert.validity_last_checked,
    async_check_requested_at: alert.async_check_requested_at,
    async_check_in_progress: alert.async_check_in_progress,
  }
  const [validation, setValidation] = useState(alertValidationDetails)
  const [groups, setGroups] = useState(alert.token_groups)
  const [showDecodedSecretDialog, setShowDecodedSecretDialog] = useState(false)

  function updateValidationWithOnDemandValidationResult(validationResult: OnDemandValidation) {
    setValidation(validationResult)
    setGroups(validationResult.token_groups)
  }

  return (
    <div>
      {showActiveSecretWithClosedAlertWarning(alertStatus, alertValidationDetails.validity) && (
        <Flash variant="danger" className="mt-1 tmp-mb-3">
          <StopIcon />
          Alert closed with an active secret. Revoke this secret through its provider to prevent unauthorized access.
        </Flash>
      )}
      <div className="border rounded-2">
        <div className={clsx('tmp-p-3', alertStatus !== AlertStatus.CLOSED && 'border-bottom')}>
          <VerificationStatusHeading
            validationDetails={validation}
            alert={alert}
            hostName={hostName}
            repo={repo}
            setValidationDetails={updateValidationWithOnDemandValidationResult}
            automaticPartnerValidityChecksEnabled={automaticPartnerValidityChecksEnabled}
          />
          <TokenLiteral rawSecret={alert.raw_secret} />
          {alert.llm_detected && <LLMDetectedBlurb />}
          {alert.is_multipart && (
            <Multipart
              tokenGroups={groups ?? []}
              repo={repo}
              alertNumber={alert.number}
              onDemandChecksSupported={alert.validation_support.on_demand_checks_supported}
              automaticValidityChecksEnabled={automaticPartnerValidityChecksEnabled}
              tokenType={alert.token_type}
              awsKeyIdStandaloneEnabled={
                alert.feature_flags?.secret_scanning_validity_checks_allowed_for_aws_keys_without_groups ?? false
              }
            />
          )}
          {alert.is_base64_encoded && (
            <>
              <div className="d-flex flex-justify-between tmp-mt-3">
                <span className="ml-1 fgColor-muted">This secret is Base64-encoded.</span>
                <Button
                  variant="link"
                  className="mr-1"
                  onClick={() => {
                    setShowDecodedSecretDialog(true)
                  }}
                >
                  View decoded secret
                </Button>
              </div>
              {showDecodedSecretDialog && (
                <Dialog
                  title="Decoded secret"
                  onClose={() => {
                    setShowDecodedSecretDialog(false)
                  }}
                >
                  <TokenLiteral rawSecret={alert.decoded_base64_raw_secret} />
                </Dialog>
              )}
            </>
          )}
        </div>
        {showRemediationSteps(alert, alertStatus, validation.validity) && (
          <div className="tmp-p-3">
            <Heading as="h3" className="f5">
              Remediation steps
            </Heading>
            <span className="fgColor-muted">Follow the steps below before you close this alert.</span>
            {oneClickReportingAvailable && isOneClickReportable(validation) ? (
              <ReportableRemediationSteps />
            ) : (
              <RemediationSteps alert={alert} verificationStatus={validation.validity} />
            )}
          </div>
        )}
        {oneClickReportingAvailable && (
          <Report alert={alert} repository={repo} setValidationDetails={setValidation} validationDetails={validation} />
        )}
      </div>
    </div>
  )
}

function showActiveSecretWithClosedAlertWarning(alertStatus: AlertStatus, verificationStatus: TokenVerificationStatus) {
  return alertStatus === AlertStatus.CLOSED && verificationStatusActive(verificationStatus)
}

function showRemediationSteps(alert: Alert, alertStatus: AlertStatus, verificationStatus: TokenVerificationStatus) {
  if (showAIAssistedRemediationGuidance(alert)) {
    return false
  }

  if (alert.low_confidence) {
    return false
  }

  if (alertStatus === AlertStatus.CLOSED) {
    return verificationStatusActive(verificationStatus)
  }

  return alertStatus === AlertStatus.OPEN
}

function TokenLiteral({rawSecret}: {rawSecret?: string | null}) {
  let literalString = ''
  let testId = ''
  let showCopyToClipboardButton = true

  if (rawSecret) {
    literalString = rawSecret
    testId = 'default-raw-secret'
  } else {
    literalString = 'No preview available'
    testId = 'no-preview-raw-secret'
    showCopyToClipboardButton = false
  }
  return (
    <div className={clsx('tmp-mt-3 p-2 d-flex flex-items-center flex-justify-between rounded-2', styles.Box)}>
      <Truncate title={literalString} inline className={clsx('p-2 width-fit f5', styles.Truncate)} data-testid={testId}>
        {literalString}
      </Truncate>
      {showCopyToClipboardButton && (
        <CopyToClipboardButton
          className="ml-auto"
          textToCopy={literalString}
          tooltipProps={{direction: 'w'}}
          ariaLabel={'Copy token'}
        />
      )}
    </div>
  )
}

// TODO remove sx
function ReportableRemediationSteps() {
  return (
    <ol data-testid="secret-scanning-remediation-steps-reportable" className={styles.Box_1}>
      <li className={styles.Box_2}>
        <CounterLabel className={styles.CounterLabel}>1</CounterLabel>
        <span>
          Review any provided metadata and reach out to the secret owner if possible to make them aware of the leak.
        </span>
      </li>
      <li className={styles.Box_2}>
        <CounterLabel className={styles.CounterLabel}>2</CounterLabel>
        <span>Rotate the secret if it&apos;s in use to prevent any breaking workflows.</span>
      </li>
      <li className={styles.Box_2}>
        <CounterLabel className={styles.CounterLabel}>3</CounterLabel>
        <span>
          Revoke this GitHub Personal Access Token to prevent unauthorized access by reporting the secret to GitHub
          below.
        </span>
      </li>
      <li className={styles.Box_2}>
        <CounterLabel className={styles.CounterLabel}>4</CounterLabel>
        <span>
          Check{' '}
          <Link
            href="https://docs.github.com/en/enterprise-cloud@latest/admin/monitoring-activity-in-your-enterprise/reviewing-audit-logs-for-your-enterprise/identifying-audit-log-events-performed-by-an-access-token"
            inline
            target="_blank"
          >
            security logs
          </Link>{' '}
          for potential breaches.
        </span>
      </li>
      <li className={styles.Box_2}>
        <CounterLabel className={styles.CounterLabel}>5</CounterLabel>
        <span>Close this alert as revoked.</span>
      </li>
    </ol>
  )
}

// TODO remove sx
function RemediationSteps({alert, verificationStatus}: {alert: Alert; verificationStatus: TokenVerificationStatus}) {
  return (
    <ol data-testid="secret-scanning-remediation-steps" className={styles.Box_1}>
      <li className={styles.Box_2}>
        <CounterLabel className={styles.CounterLabel}>1</CounterLabel>
        {verificationStatusInactive(verificationStatus) ? (
          <span data-testid="revoked-remediation-step">
            Review the {alert.label} through {alert.token_type_provider} to ensure that the secret has not been used for
            unauthorized access.
            <Link href={alert.partner_remediation_url} inline>
              {' '}
              Learn more about {alert.token_type_provider} tokens.
            </Link>
          </span>
        ) : (
          <span>Rotate the secret if it&apos;s in use to prevent breaking workflows.</span>
        )}
      </li>
      {!verificationStatusInactive(verificationStatus) ? (
        <li className={styles.Box_2}>
          <CounterLabel className={styles.CounterLabel}>2</CounterLabel>
          {alert.partner_remediation_url ? (
            <span>
              Revoke this {alert.label} through {alert.token_type_provider} to prevent unauthorized access.
              <Link href={alert.partner_remediation_url} inline>
                {' '}
                Learn more about {alert.token_type_provider} tokens.
              </Link>
            </span>
          ) : (
            <span>
              Revoke this <strong>{alert.label}</strong> through the provider to prevent unauthorized access.
            </span>
          )}
        </li>
      ) : null}
      <li className={styles.Box_2}>
        {!verificationStatusInactive(verificationStatus) ? (
          <CounterLabel className={styles.CounterLabel}>3</CounterLabel>
        ) : (
          <CounterLabel className={styles.CounterLabel}>2</CounterLabel>
        )}
        <span>Check security logs for potential breaches.</span>
      </li>
      <li className={styles.Box_2}>
        {!verificationStatusInactive(verificationStatus) ? (
          <CounterLabel className={styles.CounterLabel}>4</CounterLabel>
        ) : (
          <CounterLabel className={styles.CounterLabel}>3</CounterLabel>
        )}
        <span>Close the alert as revoked.</span>
      </li>
    </ol>
  )
}

function LLMDetectedBlurb() {
  return (
    <p className="mt-2 mb-0 fgColor-muted">
      <CopilotIcon size={16} />
      &nbsp;Detected by{' '}
      <Link
        href="https://docs.github.com/enterprise-cloud@latest/code-security/secret-scanning/using-advanced-secret-scanning-and-push-protection-features/generic-secret-detection/about-the-detection-of-generic-secrets-with-secret-scanning"
        inline
        target="_blank"
      >
        Copilot Secret Scanning
      </Link>
    </p>
  )
}
