export function secretScanningIndexPath(
  owner: string,
  repo: string,
  details?: {page?: number; query?: string; after?: string; before?: string},
) {
  const params = []
  if (details?.page) {
    params.push(`page=${details.page}`)
  }
  if (details?.query) {
    params.push(`query=${encodePart(details.query).replace(/%20/g, '+')}`)
  }
  if (details?.after) {
    params.push(`after=${encodePart(details.after)}`)
  }
  if (details?.before) {
    params.push(`before=${encodePart(details.before)}`)
  }

  return `/${encodePart(owner)}/${encodePart(repo)}/security/secret-scanning${
    params.length > 0 ? `?${params.join('&')}` : ''
  }`
}

