import {clsx} from 'clsx'
import {GitHubAvatar} from '@github-ui/github-avatar'
import {useState, useEffect, useEffectEvent} from 'react'
import {Link, Spinner, Truncate} from '@primer/react'
import {Octicon} from '@primer/react/deprecated'
import {AlertIcon} from '@primer/octicons-react'
import {type Repository, OwnerType} from '../../../types/repo-types'
import {type TokenCampaignMetadata, type TokenMetadata, TokenAccess} from '../../../types/token-metadata-types'
import {verifiedFetch} from '@github-ui/verified-fetch'
import {secretScanningTokenMetadataOrgAccessPath} from '../../../paths'

import styles from './GitHubTokenMetadataPane.module.css'
import {ViewTable, ViewTableRow} from './TokenMetadataTable'
import {TokenMetadataSection} from './TokenMetadataSection'
import {CopyToClipboardButton} from '@github-ui/copy-to-clipboard/Button'
import {useQuery} from '@github-ui/react-query'
import {
  verificationStatusToText,
  type OnDemandValidation,
  type TokenVerificationStatus,
} from '../../../types/alert-types'
import {MetadataKeys} from './MetadataKeys'

export function GitHubTokenMetadataPane({
  metadata,
  repository,
  tokenNumber,
  label,
  alertValidity,
}: {
  metadata: TokenMetadata
  campaign?: TokenCampaignMetadata
  repository: Repository
  tokenNumber: number
  label: string
  alertValidity: TokenVerificationStatus
}) {
  const shouldShowOrgAccess = repository.owner_type === OwnerType.OrgOwner

  const [orgAccess, setOrgAccess] = useState<TokenAccess>()
  const [orgAccessError, setOrgAccessError] = useState(false)

  // The code around loading token metadata for org access is beginning to get a bit gnarly
  // If you're looking at this file, and about to make further changes to how org access metadata
  // is loaded, consider extracting it into a separate component.
  const loadOrgAccess = useEffectEvent(async () => {
    if (!shouldShowOrgAccess) {
      return
    }

    const response = await verifiedFetch(
      secretScanningTokenMetadataOrgAccessPath({
        owner: repository.owner_display_login,
        repo: repository.name,
        accessId: metadata.access_id,
        tokenType: metadata.token_type,
        tokenNumber,
      }),
      {method: 'GET'},
    )

    if (response.ok) {
      const jsonData = await response.json()
      if (jsonData.org_access) {
        setOrgAccessError(false)
      } else {
        setOrgAccessError(true)
      }
      setOrgAccess(jsonData.org_access)
    } else {
      setOrgAccessError(true)
    }
  })

  useEffect(() => {
    loadOrgAccess()
  }, [orgAccessError])

  const {data: validityData} = useQuery<OnDemandValidation>({
    enabled: false,
    queryKey: ['secret-scanning', 'validation-result', tokenNumber],
    queryFn: async (): Promise<OnDemandValidation> => {
      throw new Error('it should never be called from here!')
    },
  })

  const validity = validityData?.validity ?? alertValidity

  return (
    <>
      <TokenMetadataSection>
        <ViewTable
          header={
            <>
              <span className="f6 fgColor-muted text-bold">{label}</span>
            </>
          }
          className="d-flex flex-column gap-1"
        >
          <GitHubMetadataPart
            copyable={false}
            keyName={MetadataKeys.Validity}
            bold
            textContentValue={verificationStatusToText(validity)}
          >
            {verificationStatusToText(validity)}
          </GitHubMetadataPart>

          {metadata.name && (
            <GitHubMetadataPart
              keyName={MetadataKeys.TokenName}
              copyable
              copyValue={metadata.name}
              textContentValue={metadata.name}
            >
              <TokenMetadataName metadata={metadata} />
            </GitHubMetadataPart>
          )}

          {metadata.owner && (
            <GitHubMetadataPart
              copyable
              bold
              copyValue={metadata.owner.display_login}
              keyName={MetadataKeys.SecretOwner}
              textContentValue={metadata.owner.display_login}
            >
              <div>
                {metadata.owner.avatar_url && <GitHubAvatar size={16} src={metadata.owner.avatar_url} />}
                <Link
                  href={`/${metadata.owner.display_login}/`}
                  hoverColor="accent.fg"
                  className={`${styles.Link} f6 ml-1`}
                >
                  {metadata.owner.display_login}
                </Link>
                {metadata.is_owner_suspended && <span className={`${styles.Text} f6 mb-1`}>(suspended)</span>}
              </div>
            </GitHubMetadataPart>
          )}

          <GitHubMetadataPart
            copyable
            copyValue={formattedDateString(metadata.created_at)}
            keyName={MetadataKeys.SecretIssuedDate}
            textContentValue={metadata.created_at}
          >
            <FormattedDate dateString={metadata.created_at} />
          </GitHubMetadataPart>

          <GitHubMetadataPart
            copyable={!!metadata.expires_at}
            copyValue={metadata.expires_at ? formattedDateString(metadata.expires_at) : undefined}
            keyName={MetadataKeys.SecretExpiryDate}
            textContentValue={metadata.expires_at ?? 'Secret does not expire'}
          >
            {metadata.expires_at ? (
              <FormattedDate dateString={metadata.expires_at} />
            ) : (
              <span data-testid="token-expiry-text" className="f6">
                Secret does not expire
              </span>
            )}
          </GitHubMetadataPart>

          <GitHubMetadataPart
            copyable={!!metadata.last_accessed_at}
            copyValue={metadata.last_accessed_at ? formattedDateString(metadata.last_accessed_at) : undefined}
            keyName={MetadataKeys.SecretLastUsedDate}
            textContentValue={metadata.last_accessed_at ?? 'Never used'}
          >
            {metadata.last_accessed_at ? (
              <FormattedDate dateString={metadata.last_accessed_at} />
            ) : (
              <span data-testid="token-last-used-text" className="f6">
                Never used
              </span>
            )}
          </GitHubMetadataPart>

          {shouldShowOrgAccess &&
            (orgAccess ? (
              <GitHubMetadataPart
                copyable={false}
                keyName={MetadataKeys.OrganizationAccess}
                textContentValue={`${getTokenAccessPrefix(orgAccess)} ${repository.owner_display_login} ${
                  orgAccess === TokenAccess.PublicAccess ? '(public resources only)' : ''
                }`}
              >
                <span data-testid="token-access-text" className="f6">
                  {getTokenAccessPrefix(orgAccess)}
                  <b>{repository.owner_display_login}</b>
                  {orgAccess === TokenAccess.PublicAccess && <span> (public resources only)</span>}
                </span>
              </GitHubMetadataPart>
            ) : (
              <GitHubMetadataPart
                copyable={false}
                keyName={MetadataKeys.OrganizationAccess}
                textContentValue="Loading organization access"
              >
                <LoadingOrgAccess error={orgAccessError} />
              </GitHubMetadataPart>
            ))}
        </ViewTable>
      </TokenMetadataSection>
    </>
  )
}

function GitHubMetadataPart({
  keyName,
  children,
  copyable,
  copyValue,
  bold = false,
  textContentValue,
}: {
  keyName: string
  children?: React.ReactNode
  copyable: boolean
  copyValue?: string
  bold?: boolean
  textContentValue: string
}) {
  return (
    <ViewTableRow keyCell={keyName}>
      {/* Need d-block to get truncation to work */}
      <Truncate title={copyValue ?? textContentValue} className={clsx('d-block', bold && 'text-superbold')}>
        {children}
      </Truncate>
      <CopyToClipboardButton
        // v-hidden used to hide button so that it still takes up space and keeps row height consistent
        className={clsx('ml-auto', !copyable && 'v-hidden')}
        textToCopy={copyValue ?? ''}
      />
    </ViewTableRow>
  )
}

function LoadingOrgAccess({error}: {error: boolean}) {
  return (
    <div>
      {error ? (
        <div>
          <Octicon icon={AlertIcon} className={styles.Octicon} />
          <span className="f6">Failed to load organization access</span>
        </div>
      ) : (
        <div>
          <span className="f6">{'Loading'}</span>
          <Spinner size={'small'} className={styles.Spinner} />
        </div>
      )}
    </div>
  )
}

function formattedDateString(dateString: string): string {
  const date = new Date(dateString)
  return date.toLocaleDateString('en-US', {month: 'long', year: 'numeric', day: 'numeric'})
}

function FormattedDate({dateString}: {dateString: string}) {
  return (
    <div>
      <span className="f6">{formattedDateString(dateString)}</span>
    </div>
  )
}

function TokenMetadataName({metadata}: {metadata: TokenMetadata}) {
  if (metadata.link) {
    return (
      <Link href={metadata.link} className="f6">
        {metadata.name}
      </Link>
    )
  }
  return <span className="f6">{metadata.name}</span>
}

function getTokenAccessPrefix(orgAccess: TokenAccess): string {
  switch (orgAccess) {
    case TokenAccess.OrgAccess:
    case TokenAccess.PublicAccess:
      return `Access to `
    case TokenAccess.SSOAccess:
      return `SSO access to `
    default:
      return `No access to `
  }
}
