import {clsx} from 'clsx'

export function ViewTable({
  header,
  className,
  children,
}: {
  header: React.ReactNode
  className?: string
  children: React.ReactNode
}) {
  return (
    <div className="border rounded-2">
      <div className="border-bottom tmp-px-3 py-2.5">{header}</div>
      <div className={clsx('tmp-px-3 py-2', className)}>{children}</div>
    </div>
  )
}

export function ViewTableRow({
  style,
  keyCell,
  children,
  ...props
}: {
  style?: React.CSSProperties
  keyCell?: React.ReactNode
  children: React.ReactNode
  'data-testid'?: string
}) {
  return (
    <div className={'d-flex flex-items-center f6'} style={style} data-testid={props['data-testid']}>
      <span className="pr-1 col-5 flex-shrink-0 fgColor-muted text-bold">{keyCell}</span>
      {children}
    </div>
  )
}
