import {GitHubAvatar} from '@github-ui/github-avatar'
import {hovercardAttributesForActor} from '@github-ui/hovercards'
import type {DisplayedUser} from '../../types/user-types'

export interface UserComponentProps {
  user: DisplayedUser | null
  showDisplayName?: boolean
  size?: number
  testId?: string
  className?: string
}

/**
 * A reusable component for displaying user information (avatar and optionally display name).
 */
export function UserComponent({
  user,
  showDisplayName = true,
  size = 16,
  testId = 'user-component',
  className = '',
}: UserComponentProps) {
  if (!user) {
    return null
  }

  const hovercardAttributes = hovercardAttributesForActor(user.display_login)

  return (
    <div data-testid={testId} className={className}>
      <GitHubAvatar
        size={size}
        src={user.avatar_url || 'https://avatars.githubusercontent.com/ghost'}
        {...hovercardAttributes}
      />
      {showDisplayName && <span className="ml-1 text-bold">{user.display_login}</span>}
    </div>
  )
}
