import {ActionList} from '@primer/react'
import type {RelatedAlerts} from '../../../types/alert-types'
import {TokenMetadataSection} from './TokenMetadataSection'
import RepositoryLabel from '../../shared/RepositoryLabel'
import {secretScanningAlertPath} from '../../../paths'
import type {Repository} from '../../../types/repo-types'

export function RelatedAlertsPane({relatedAlerts, repository}: {relatedAlerts: RelatedAlerts; repository: Repository}) {
  const scope = repository.owner_belongs_to_business ? 'enterprise' : 'organization'
  return (
    <TokenMetadataSection sectionName="Related alerts">
      <ActionList variant="full">
        {relatedAlerts.alerts.map(alert => (
          <RepositoryLabel
            key={`${alert.repository_id}-${alert.number}`}
            name={`${alert.repository_owner}/${alert.repository_name}`}
            icon={alert.repository_icon}
            href={secretScanningAlertPath(alert.repository_owner, alert.repository_name, alert.number)}
          />
        ))}
      </ActionList>
      {relatedAlerts.more_exist && relatedAlerts.alerts.length === 5 && <span>Note: this list is not exhaustive.</span>}
      {relatedAlerts.more_exist && relatedAlerts.alerts.length < 5 && (
        <span>There are additional alerts in {scope} repositories that you do not have the permissions to view.</span>
      )}
    </TokenMetadataSection>
  )
}
