import {BlankslateType, type BlankslatePayload, type BlankslateEnterprisePayload} from '../../types/blankslate'
import {Link} from '@primer/react'
import {aboutTokenScanningPath, securityAnalysisSettingsPath, secretScanningIndexPath} from '../../paths'

import styles from './IndexBlankslate.module.css'
import {useClickAnalytics} from '@github-ui/use-analytics'
import {Blankslate} from './Blankslate'

export function IndexBlankslate({payload}: {payload: BlankslatePayload | BlankslateEnterprisePayload}) {
  const {sendClickAnalyticsEvent} = useClickAnalytics()

  const handleCtaClick = () => {
    const targetUrl = securityAnalysisSettingsPath(payload.repository.owner_display_login, payload.repository.name)
    const viewUrl = secretScanningIndexPath(payload.repository.owner_display_login, payload.repository.name)

    sendClickAnalyticsEvent({
      label: 'Enable secret scanning in this repo',
      target_url: targetUrl,
      view: viewUrl,
    })
  }

  switch (payload.blankslate_type) {
    case BlankslateType.Disabled:
      if (payload.adminable) {
        return (
          <IndexBlankslateBox>
            <Blankslate
              title="Secret scanning is not enabled"
              action={
                <Link
                  href={securityAnalysisSettingsPath(payload.repository.owner_display_login, payload.repository.name)}
                  onClick={handleCtaClick}
                  data-testid={'blankslate-link'}
                  inline
                >
                  Enable secret scanning in this repo
                </Link>
              }
            >
              Secret scanning is a security feature that helps detect and prevent the accidental inclusion of sensitive
              information in your repository. To put it to work, you&apos;ll need to enable it in your repository&apos;s
              Advanced Security settings.
            </Blankslate>
          </IndexBlankslateBox>
        )
      } else {
        return (
          <IndexBlankslateBox>
            <Blankslate title="Secret scanning disabled">
              {'Secret scanning has not yet been enabled by a user with admin permissions for this repository. '}
              <Link
                inline
                href={aboutTokenScanningPath(payload.help_url)}
                target={'_blank'}
                data-testid={'blankslate-link'}
              >
                Learn more about secret scanning.
              </Link>
            </Blankslate>
          </IndexBlankslateBox>
        )
      }
    case BlankslateType.LoadingFailed:
      if ('enterprise_contact_path' in payload) {
        return (
          <IndexBlankslateBox>
            <Blankslate title="Loading secrets failed">
              If the problem persists please{' '}
              <Link inline href={payload.enterprise_contact_path} data-testid={'blankslate-link'}>
                {'contact support'}
              </Link>
              .
            </Blankslate>
          </IndexBlankslateBox>
        )
      } else {
        return (
          <IndexBlankslateBox>
            <Blankslate title="Loading secrets failed">
              We track these errors automatically, but if the problem persists feel free to{' '}
              <Link inline href="https://support.github.com/" data-testid={'blankslate-link'}>
                {'contact us'}
              </Link>
              .
            </Blankslate>
          </IndexBlankslateBox>
        )
      }
  }
}

function IndexBlankslateBox({children}: {children: React.ReactNode}) {
  return (
    <div data-testid={'blankslate-container'} className={styles.Box}>
      {children}
    </div>
  )
}
