import {Header, Details, useDetails} from '@primer/react'
import {Octicon} from '@primer/react/deprecated'
import {ChevronDownIcon, ChevronRightIcon} from '@primer/octicons-react'

export interface RemediationStepTemplateProps {
  children?: React.ReactNode
  stepIndex: number
  headingText: string
  isDefaultExpanded?: boolean
  onExpand: (e: React.SyntheticEvent<HTMLElement>) => void
  isFirstStep: boolean
  isLastStep: boolean
}

export function RemediationStepTemplate({
  children,
  stepIndex,
  headingText,
  isDefaultExpanded = false,
  onExpand,
  isFirstStep,
  isLastStep,
}: RemediationStepTemplateProps) {
  const {getDetailsProps, open} = useDetails({closeOnOutsideClick: false, defaultOpen: isDefaultExpanded})
  const onToggle = getDetailsProps().onToggle

  const onDetailsToggle = (e: React.SyntheticEvent<HTMLElement>) => {
    onToggle(e)
    onExpand(e)
  }

  let border = ''
  if (isFirstStep) {
    border = 'border rounded-top-2 border-sm-bottom-0 border-md-bottom-0 border-lg-bottom-0 border-xl-bottom-0'
  }
  if (isLastStep) {
    border = 'border rounded-bottom-2'
  }
  if (!isFirstStep && !isLastStep) {
    border = 'border border-sm-bottom-0 border-md-bottom-0 border-lg-bottom-0 border-xl-bottom-0'
  }

  return (
    <div className={`p-1 ${border}`}>
      <Details {...getDetailsProps()} onToggle={onDetailsToggle}>
        <Header as="summary" className="tmp-p-3 bgColor-default">
          <Header.Item>
            <Octicon
              icon={open ? ChevronDownIcon : ChevronRightIcon}
              className="fgColor-muted ml-auto mr-1"
              aria-label={open ? 'Hide step' : 'Show step'}
            />
          </Header.Item>
          <Header.Item className="mr-0">
            <div className="f4 text-semibold fgColor-default">
              {stepIndex}. {headingText}
            </div>
          </Header.Item>
        </Header>
        <div className="pl-2 pr-2 pb-2 pt-1">{children}</div>
      </Details>
    </div>
  )
}
