import {Flash, Heading, IconButton} from '@primer/react'
import {MarkGithubIcon, XIcon} from '@primer/octicons-react'
import {reactFetchJSON} from '@github-ui/verified-fetch'
import {useState, type ReactNode} from 'react'
import {dismissNoticePath} from '../../paths'

export function UserFeedbackBanner({
  showBannerOnLoad,
  notice,
  children,
}: {
  showBannerOnLoad: boolean
  notice: string
  children: ReactNode
}) {
  const [showBanner, setShowBanner] = useState(showBannerOnLoad)

  const onDismiss = async () => {
    const result = await reactFetchJSON(dismissNoticePath({notice}), {method: 'POST'})

    if (result.ok) {
      setShowBanner(false)
    }
  }

  return showBanner ? (
    <Flash className="tmp-mb-3 p-2" data-testid="user-feedback-banner">
      <div className="d-flex">
        <MarkGithubIcon className="mt-1" />
        <Heading as="h4" className="f4">
          Can you give us some feedback?
        </Heading>
        <IconButton
          aria-label="Hide this notice forever"
          size="small"
          variant="invisible"
          icon={XIcon}
          className="ml-auto pl-2 py-1 pr-0"
          data-testid="dismiss-notice-button"
          onClick={onDismiss}
        />
      </div>
      <div>{children}</div>
    </Flash>
  ) : null
}
